import math

# Unconditional Day 1 MI across all 40 employees (31 have 1 regular doc on Day 1, 9 have 0)
# Never put any of the 9 Engineering employees in Day 1 canary (that would create new leak risk!).
# Among the 31 employees who ALREADY have 1 regular doc on Day 1, choose k employees for 1 canary (3 variants).
# Even better: remember d1-1 (14) and d1-2 (17) are DIFFERENT regular docs!
# So the Day 1 outcome ALREADY distinguishes 'd1-1' vs 'd1-2'!
# Let's compute I(Mole; Day1_Outcome) WITH 1 canary of size k vs WITHOUT any canary!

def day1_mi(k1, k2=0):
    # Suppose Canary 1 has k1 people in d1-1 U d1-2, Canary 2 (disjoint) has k2 people in d1-1 U d1-2
    # Wait: what if Canary 1 and Canary 2 OVERLAP (orthogonal 3x3 grid on 9 or 18 people)?!
    pass

# Let's test arbitrary assignments of up to 2 canaries on the 31 active employees!
# Group A: 14 employees (hold d1-1)
# Group B: 17 employees (hold d1-2)
# Group E: 9 employees (hold nothing)

def eval_plan(c1_assign, c2_assign=None):
    # c1_assign: dict emp_idx (0..30) -> 0,1,2
    # c2_assign: dict emp_idx (0..30) -> 0,1,2 or None
    w1 = 1.0 - len(c1_assign) / 40.0 if c1_assign else 0.0
    w2 = 1.0 - len(c2_assign) / 40.0 if c2_assign else 0.0
    p_leak = 0.65
    outcomes = ['none', 'd1-1', 'd1-2', 'c1_0', 'c1_1', 'c1_2', 'c2_0', 'c2_1', 'c2_2']
    cond = []
    for i in range(40):
        d = {o: 0.0 for o in outcomes}
        if i >= 31:
            d['none'] = 1.0
        else:
            reg = 'd1-1' if i < 14 else 'd1-2'
            tot_w = 1.0 + (w1 if i in c1_assign else 0.0) + (w2 if (c2_assign and i in c2_assign) else 0.0)
            d['none'] = 1.0 - p_leak
            d[reg] = p_leak * (1.0 / tot_w)
            if i in c1_assign:
                v = c1_assign[i]
                pc = p_leak * (w1 / tot_w)
                for u in range(3):
                    d[f'c1_{u}'] = pc * (0.95 if u == v else 0.025)
            if c2_assign and i in c2_assign:
                v = c2_assign[i]
                pc = p_leak * (w2 / tot_w)
                for u in range(3):
                    d[f'c2_{u}'] = pc * (0.95 if u == v else 0.025)
        cond.append(d)
    marg = {o: sum(cond[i][o] / 40.0 for i in range(40)) for o in outcomes}
    mi = 0.0
    for i in range(40):
        for o in outcomes:
            p = (1.0 / 40.0) * cond[i][o]
            if p > 0:
                mi += p * math.log2(cond[i][o] / marg[o])
    return mi

base_mi = eval_plan({})
print(f"Base MI (0 canaries): {base_mi:.4f} bits")

for k in range(3, 32):
    # Pick k employees balanced across Group A and Group B
    c1 = {i: i % 3 for i in range(k)}
    mi = eval_plan(c1)
    if k in [6, 9, 12, 15, 18, 21, 24, 27, 30, 31]:
        print(f"1 canary size {k:2d}: MI={mi:.4f} (+{mi - base_mi:.4f} bits)")

# Disjoint 2 canaries: k1 in A, k2 in B
for k1, k2 in [(9, 9), (9, 12), (12, 12), (14, 17)]:
    c1 = {i: i % 3 for i in range(k1)}
    c2 = {14 + i: i % 3 for i in range(k2)}
    mi = eval_plan(c1, c2)
    print(f"2 disjoint canaries ({k1}, {k2}): MI={mi:.4f} (+{mi - base_mi:.4f} bits)")

# Overlapping 2 canaries on 18 employees (orthogonal 3x3 grid, 2 per cell!)
c1 = {i: (i // 3) % 3 for i in range(18)}
c2 = {i: i % 3 for i in range(18)}
mi = eval_plan(c1, c2)
print(f"2 overlapping canaries (18, 18): MI={mi:.4f} (+{mi - base_mi:.4f} bits)")
